INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_001', 'math', 'คณิตศาสตร์', 'Regular', 1, 'จำนวนนับและค่าประจำหลัก', 'เลข 5 ในจำนวน 358,412 กับเลข 5 ในจำนวน 72,509 มีค่าต่างกันเท่าใด', '["45,000","49,500","50,000","50,500"]', 1, '5 ใน 358,412 มีค่า 50,000 และ 5 ใน 72,509 มีค่า 500
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_002', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การประมาณค่าใกล้เคียง', 'ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84,679 คือข้อใด', '["84,000","84,700","85,000","85,600"]', 2, 'ดูหลักร้อยคือเลข 6 ซึ่งมากกว่าหรือเท่ากับ 5 ให้ปัดขึ้นเป็น 85,000', 'ระวังสับสนระหว่างเต็มร้อยกับเต็มพัน', 'การประมาณค่าใกล้เคียงจำนวนเต็ม', '["การประมาณค่าใกล้เคียง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_003', 'math', 'คณิตศาสตร์', 'Regular', 1, 'สมบัติการแจกแจง', '\( (38 \times 65) + (38 \times 35) \) มีค่าเท่ากับข้อใด', '["3,800","3,500","2,650","1,900"]', 0, '38 x (65 + 35) = 38 x 100 = 3,800', 'อย่าเสียเวลาคูณทีละคู่', 'สมบัติการแจกแจง a(b+c)', '["สมบัติการแจกแจง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_004', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การแยกตัวประกอบ', 'ข้อใดเขียนการแยกตัวประกอบของ 72 ในรูปเลขยกกำลังได้ถูกต้อง', '["8 x 9","2 x 3 x 12","\\( 2^3 \\times 3^2 \\)","\\( 2^2 \\times 3^3 \\)"]', 2, '72 = 8 x 9 = \( 2^3 \times 3^2 \)', 'ฐานต้องเป็นจำนวนเฉพาะเท่านั้น', 'จำนวนเฉพาะและการแยกตัวประกอบ', '["การแยกตัวประกอบ","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_005', 'math', 'คณิตศาสตร์', 'Regular', 1, 'ห.ร.ม.', 'ห.ร.ม. ของ 36, 54 และ 90 คือข้อใด', '["6","9","18","27"]', 2, 'นำ 9 ไปหารได้ 4, 6, 10 จากนั้นนำ 2 ไปหารได้ 2, 3, 5
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_006', 'math', 'คณิตศาสตร์', 'Regular', 1, 'ค.ร.น.', 'ค.ร.น. ของ 12, 18 และ 24 คือข้อใด', '["48","72","96","144"]', 1, 'พหุคูณร่วมที่น้อยที่สุดที่ทั้งสามจำนวนหารลงตัวคือ 72', 'ระวังสับสนระหว่าง ห.ร.ม. กับ ค.ร.น.', 'การหา ค.ร.น. ด้วยวิธีตั้งหารสั้น', '["ค.ร.น.","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_007', 'math', 'คณิตศาสตร์', 'Regular', 1, 'ความสัมพันธ์ ห.ร.ม. และ ค.ร.น.', 'สองจำนวนมี ห.ร.ม. = 6 และ ค.ร.น. = 120 ถ้าจำนวนแรกคือ 24 อีกจำนวนคือข้อใด', '["20","30","36","40"]', 1, '(6 x 120) / 24 = 720 / 24 = 30', 'ต้องจำสูตรผลคูณ 2 จำนวน = ห.ร.ม. x ค.ร.น.', 'ทฤษฎี A x B = ห.ร.ม. x ค.ร.น.', '["ความสัมพันธ์ ห.ร.ม. และ ค.ร.น.","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_008', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การเรียงลำดับเศษส่วน', 'ข้อใดเรียงลำดับเศษส่วนจากน้อยไปมากได้ถูกต้อง', '["\\( \\frac{1}{2}, \\frac{3}{5}, \\frac{2}{3} \\)","\\( \\frac{3}{5}, \\frac{1}{2}, \\frac{2}{3} \\)","\\( \\frac{2}{3}, \\frac{3}{5}, \\frac{1}{2} \\)","\\( \\frac{1}{2}, \\frac{2}{3}, \\frac{3}{5} \\)"]', 0, 'ทำส่วนให้เป็น 30: 15/30 < 18/30 < 20/30', 'ทำส่วนให้เท่ากันก่อนเปรียบเทียบ', 'การเปรียบเทียบและเรียงลำดับเศษส่วน', '["การเรียงลำดับเศษส่วน","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_009', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การบวกและลบเศษส่วนคละ', '\( 3\frac{1}{4} - 1\frac{2}{3} \) มีค่าเท่ากับข้อใด', '["\\( 1\\frac{7}{12} \\)","\\( 1\\frac{5}{12} \\)","\\( 2\\frac{1}{12} \\)","\\( 2\\frac{7}{12} \\)"]', 0, '\( 3\frac{3}{12} - 1\frac{8}{12} = 2\frac{15}{12} - 1\frac{8}{12} = 1\frac{7}{12} \)', 'ระวังการยืมจำนวนเต็ม', 'การบวกและการลบจำนวนคละ', '["การบวกและลบเศษส่วนคละ","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_010', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การคูณและหารเศษส่วน', '\( \frac{4}{9} \div \frac{8}{15} \times \frac{6}{5} \) มีค่าเท่ากับข้อใด', '["\\( \\frac{2}{3} \\)","1","\\( \\frac{4}{3} \\)","\\( \\frac{3}{2} \\)"]', 1, '(4/9) x (15/8) x (6/5) = 360/360 = 1', 'เปลี่ยนหารเป็นคูณกลับเศษเป็นส่วน', 'การคูณและการหารเศษส่วน', '["การคูณและหารเศษส่วน","Regular","L1"]');
