INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_028', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การเรียงลำดับเศษส่วน', 'ข้อใดเรียงลำดับเศษส่วนจากน้อยไปมากได้ถูกต้อง (ชุดที่ 3)', '["\\( \\frac{1}{2}, \\frac{3}{5}, \\frac{2}{3} \\)","\\( \\frac{3}{5}, \\frac{1}{2}, \\frac{2}{3} \\)","\\( \\frac{2}{3}, \\frac{3}{5}, \\frac{1}{2} \\)","\\( \\frac{1}{2}, \\frac{2}{3}, \\frac{3}{5} \\)"]', 0, 'ทำส่วนให้เป็น 30: 15/30 < 18/30 < 20/30', 'ทำส่วนให้เท่ากันก่อนเปรียบเทียบ', 'การเปรียบเทียบและเรียงลำดับเศษส่วน', '["การเรียงลำดับเศษส่วน","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_029', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การบวกและลบเศษส่วนคละ', '\( 3\frac{1}{4} - 1\frac{2}{3} \) มีค่าเท่ากับข้อใด (ชุดที่ 3)', '["\\( 1\\frac{7}{12} \\)","\\( 1\\frac{5}{12} \\)","\\( 2\\frac{1}{12} \\)","\\( 2\\frac{7}{12} \\)"]', 0, '\( 3\frac{3}{12} - 1\frac{8}{12} = 2\frac{15}{12} - 1\frac{8}{12} = 1\frac{7}{12} \)', 'ระวังการยืมจำนวนเต็ม', 'การบวกและการลบจำนวนคละ', '["การบวกและลบเศษส่วนคละ","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_030', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การคูณและหารเศษส่วน', '\( \frac{4}{9} \div \frac{8}{15} \times \frac{6}{5} \) มีค่าเท่ากับข้อใด (ชุดที่ 3)', '["\\( \\frac{2}{3} \\)","1","\\( \\frac{4}{3} \\)","\\( \\frac{3}{2} \\)"]', 1, '(4/9) x (15/8) x (6/5) = 360/360 = 1', 'เปลี่ยนหารเป็นคูณกลับเศษเป็นส่วน', 'การคูณและการหารเศษส่วน', '["การคูณและหารเศษส่วน","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_031', 'math', 'คณิตศาสตร์', 'Regular', 1, 'จำนวนนับและค่าประจำหลัก', 'เลข 5 ในจำนวน 358,412 กับเลข 5 ในจำนวน 72,509 มีค่าต่างกันเท่าใด (ชุดที่ 4)', '["45,000","49,500","50,000","50,500"]', 1, '5 ใน 358,412 มีค่า 50,000 และ 5 ใน 72,509 มีค่า 500
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_032', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การประมาณค่าใกล้เคียง', 'ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84,679 คือข้อใด (ชุดที่ 4)', '["84,000","84,700","85,000","85,600"]', 2, 'ดูหลักร้อยคือเลข 6 ซึ่งมากกว่าหรือเท่ากับ 5 ให้ปัดขึ้นเป็น 85,000', 'ระวังสับสนระหว่างเต็มร้อยกับเต็มพัน', 'การประมาณค่าใกล้เคียงจำนวนเต็ม', '["การประมาณค่าใกล้เคียง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_033', 'math', 'คณิตศาสตร์', 'Regular', 1, 'สมบัติการแจกแจง', '\( (38 \times 65) + (38 \times 35) \) มีค่าเท่ากับข้อใด (ชุดที่ 4)', '["3,800","3,500","2,650","1,900"]', 0, '38 x (65 + 35) = 38 x 100 = 3,800', 'อย่าเสียเวลาคูณทีละคู่', 'สมบัติการแจกแจง a(b+c)', '["สมบัติการแจกแจง","Regular","L1"]');
