INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_001', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ท่อลำเลียงพืช', 'เนื้อเยื่อลำเลียงที่ทำหน้าที่ลำเลียงน้ำและแร่ธาตุจากรากขึ้นไปสู่ส่วนต่างๆ ของพืชเรียกว่าอะไร', '["โฟลเอ็ม (Phloem)","คอร์เทกซ์ (Cortex)","ไซเล็ม (Xylem)","ปากใบ (Stoma)"]', 2, 'ไซเล็ม (Xylem) ลำเลียงน้ำและแร่ธาตุขึ้นทางเดียว ส่วนโฟลเอ็ม (Phloem) ลำเลียงอาหารที่พืชสร้างขึ้นได้ทุกทิศทาง', 'ระวังสับสนระหว่างไซเล็มกับโฟลเอ็ม', 'ไซเล็ม = น้ำ, โฟลเอ็ม = อาหาร', '["ท่อลำเลียงพืช","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_002', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'การสังเคราะห์ด้วยแสง', 'สารใดเป็นผลผลิตหลักที่เกิดจากกระบวนการสังเคราะห์ด้วยแสงของพืชควบคู่กับแก๊สออกซิเจน', '["น้ำตาลกลูโคส","แก๊สคาร์บอนไดออกไซด์","กรดอะมิโน","โปรตีน"]', 0, 'การสังเคราะห์ด้วยแสงเปลี่ยนแก๊สคาร์บอนไดออกไซด์และน้ำ โดยใช้แสงและคลอโรฟิลล์ ได้น้ำตาลกลูโคสและแก๊สออกซิเจน', 'น้ำตาลกลูโคสคือผลผลิตหลัก ส่วนออกซิเจนคือผลพลอยได้', 'CO2 + H2O -> กลูโคส + O2', '["การสังเคราะห์ด้วยแสง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_003', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โครงสร้างดอกไม้', 'ส่วนประกอบใดของดอกที่จะเจริญไปเป็น ''ผล'' หลังจากการปฏิสนธิเรียบร้อยแล้ว', '["ออวุล (Ovule)","รังไข่ (Ovary)","ละอองเรณู (Pollen)","กลีบเลี้ยง (Sepal)"]', 1, 'รังไข่ (Ovary) เจริญไปเป็นผล ส่วนออวุล (Ovule) ด้านในจะเจริญไปเป็นเมล็ด', 'รังไข่ -> ผล, ออวุล -> เมล็ด', 'รังไข่กลายเป็นผล ออวุลกลายเป็นเมล็ด', '["โครงสร้างดอกไม้","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_004', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'สัตว์เลี้ยงลูกด้วยน้ำนม', 'สัตว์ในข้อใดจัดเป็นสัตว์เลือดอุ่นที่เลี้ยงลูกด้วยน้ำนมทั้งหมด', '["กบ เพนกวิน จระเข้","ตุ่นปากเป็ด ตุ่นปากเป็ด เป็ด","ปลาวาฬ ปลาโลมา ค้างคาว","วาฬ โลมา ค้างคาว"]', 3, 'วาฬ โลมา และค้างคาว ออกลูกเป็นตัว เลี้ยงลูกด้วยน้ำนม และเป็นสัตว์เลือดอุ่น', 'วาฬและโลมาไม่ใช่ปลาแต่เป็นสัตว์เลี้ยงลูกด้วยน้ำนม', 'วาฬ โลมา ค้างคาว = สัตว์เลี้ยงลูกด้วยน้ำนม', '["สัตว์เลี้ยงลูกด้วยน้ำนม","Regular","L1"]');
