INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_047', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'การสังเคราะห์ด้วยแสง', 'สารใดเป็นผลผลิตหลักที่เกิดจากกระบวนการสังเคราะห์ด้วยแสงของพืชควบคู่กับแก๊สออกซิเจน (ชุดที่ 10)', '["น้ำตาลกลูโคส","แก๊สคาร์บอนไดออกไซด์","กรดอะมิโน","โปรตีน"]', 0, 'การสังเคราะห์ด้วยแสงเปลี่ยนแก๊สคาร์บอนไดออกไซด์และน้ำ โดยใช้แสงและคลอโรฟิลล์ ได้น้ำตาลกลูโคสและแก๊สออกซิเจน', 'น้ำตาลกลูโคสคือผลผลิตหลัก ส่วนออกซิเจนคือผลพลอยได้', 'CO2 + H2O -> กลูโคส + O2', '["การสังเคราะห์ด้วยแสง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_048', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'โครงสร้างดอกไม้', 'ส่วนประกอบใดของดอกที่จะเจริญไปเป็น ''ผล'' หลังจากการปฏิสนธิเรียบร้อยแล้ว (ชุดที่ 10)', '["ออวุล (Ovule)","รังไข่ (Ovary)","ละอองเรณู (Pollen)","กลีบเลี้ยง (Sepal)"]', 1, 'รังไข่ (Ovary) เจริญไปเป็นผล ส่วนออวุล (Ovule) ด้านในจะเจริญไปเป็นเมล็ด', 'รังไข่ -> ผล, ออวุล -> เมล็ด', 'รังไข่กลายเป็นผล ออวุลกลายเป็นเมล็ด', '["โครงสร้างดอกไม้","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_049', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'สัตว์เลี้ยงลูกด้วยน้ำนม', 'สัตว์ในข้อใดจัดเป็นสัตว์เลือดอุ่นที่เลี้ยงลูกด้วยน้ำนมทั้งหมด (ชุดที่ 10)', '["กบ เพนกวิน จระเข้","ตุ่นปากเป็ด ตุ่นปากเป็ด เป็ด","ปลาวาฬ ปลาโลมา ค้างคาว","วาฬ โลมา ค้างคาว"]', 3, 'วาฬ โลมา และค้างคาว ออกลูกเป็นตัว เลี้ยงลูกด้วยน้ำนม และเป็นสัตว์เลือดอุ่น', 'วาฬและโลมาไม่ใช่ปลาแต่เป็นสัตว์เลี้ยงลูกด้วยน้ำนม', 'วาฬ โลมา ค้างคาว = สัตว์เลี้ยงลูกด้วยน้ำนม', '["สัตว์เลี้ยงลูกด้วยน้ำนม","Regular","L1"]');
