INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('THAI_001', 'thai', 'ภาษาไทย', 'Regular', 1, 'อักษรสามหมู่', 'พยัญชนะในข้อใดจัดอยู่ในกลุ่ม ''อักษรสูง'' ทั้งหมด', '["ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห","ก จ ด ต บ ป อ","ค ฅ ฆ ง ช ซ","ท ธ น พ ฟ ภ ม ย ร ล ว"]', 0, 'อักษรสูงมี 11 ตัว ได้แก่ ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห (เทคนิคจำ: ผีฝากถุงข้าวสารให้ฉัน)', 'ท่องจำอักษรสูง 11 ตัวให้แม่น', 'ผีฝากถุงข้าวสารให้ฉัน', '["อักษรสามหมู่","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('THAI_002', 'thai', 'ภาษาไทย', 'Regular', 1, 'การผันวรรณยุกต์', 'คำว่า ''บ้าน'' มีเสียงวรรณยุกต์ตรงกับข้อใด', '["เสียงสามัญ","เสียงเอก","เสียงโท","เสียงตรี"]', 2, 'คำว่า ''บ้าน'' พยัญชนะต้นเป็นอักษรกลาง (บ) เป็นคำเป็น ผันได้รูปโทตรงกับเสียงโท', 'อักษรกลางคำเป็น รูปและเสียงตรงกันทั้ง 5 เสียง', 'อักษรกลาง รูปโท = เสียงโท', '["การผันวรรณยุกต์","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('THAI_003', 'thai', 'ภาษาไทย', 'Regular', 1, 'มาตราแม่กด', 'คำในข้อใดมีตัวสะกดอยู่ใน ''มาตราแม่กด'' ทั้งหมด', '["ตรวจ ตำรวจ บวช","เคารพ รูปภาพ ลาภ","โบราณ คุณ วาฬ","เมฆ เลข วิหค"]', 0, 'จ, ช, รวจ เมื่อทำหน้าที่เป็นตัวสะกดจะออกเสียงเหมือน ด สะกด จัดอยู่ในมาตราแม่กด', 'จ ช รวจ ออกเสียงเหมือน ด สะกด', 'แม่กด = จ ช ซ ฎ ฏ ฐ ฑ ฒ ด ต ถ ท ธ ศ ษ ส', '["มาตราแม่กด","Regular","L1"]');
