INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_001', 'social', 'สังคมศึกษา', 'Regular', 1, 'วันสำคัญทางพุทธศาสนา', 'เหตุการณ์ ''ประสูติ ตรัสรู้ และปรินิพพาน'' ของพระสัมมาสัมพุทธเจ้า ตรงกับวันสำคัญทางพระพุทธศาสนาในข้อใด', '["วันมาฆบูชา","วันวิสาขบูชา","วันอาสาฬหบูชา","วันอัฏฐมีบูชา"]', 1, 'วันวิสาขบูชา ตรงกับวันเพ็ญ 15 ค่ำ เดือน 6 เป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพาน', 'วิสาขบูชา = ประสูติ ตรัสรู้ ปรินิพพาน (ขึ้น 15 ค่ำ เดือน 6)', 'วิสาขะ = 3 เหตุการณ์อัศจรรย์วันเพ็ญเดือน 6', '["วันสำคัญทางพุทธศาสนา","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_002', 'social', 'สังคมศึกษา', 'Regular', 1, 'อิทธิบาท ๔', 'หลักธรรม ''อิทธิบาท ๔'' (ฉันทะ วิริยะ จิตตะ วิมังสา) เป็นหลักธรรมที่ส่งเสริมความสำเร็จในเรื่องใดโดยตรง', '["การทำงานและการเรียนให้ประสบความสำเร็จ","การอยู่ร่วมกันในสังคมอย่างสันติสุข","การรักษาทรัพย์สมบัติไม่ให้สูญหาย","การป้องกันโรคภัยไข้เจ็บ"]', 0, 'อิทธิบาท 4 คือ คุณธรรมที่นำไปสู่ความสำเร็จแห่งผลที่มุ่งหมาย (ฉันทะ=พอใจรักใคร่, วิริยะ=พากเพียร, จิตตะ=เอาใจใส่, วิมังสา=ไตร่ตรอง)', 'อิทธิบาท 4 = คุณธรรมแห่งความสำเร็จในการทำงานและการเรียน', 'ฉันทะ วิริยะ จิตตะ วิมังสา = สำเร็จ', '["อิทธิบาท ๔","Regular","L1"]');
