INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_099', 'social', 'สังคมศึกษา', 'Regular', 1, 'วันสำคัญทางพุทธศาสนา', 'เหตุการณ์ ''ประสูติ ตรัสรู้ และปรินิพพาน'' ของพระสัมมาสัมพุทธเจ้า ตรงกับวันสำคัญทางพระพุทธศาสนาในข้อใด (ชุดที่ 50)', '["วันมาฆบูชา","วันวิสาขบูชา","วันอาสาฬหบูชา","วันอัฏฐมีบูชา"]', 1, 'วันวิสาขบูชา ตรงกับวันเพ็ญ 15 ค่ำ เดือน 6 เป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพาน', 'วิสาขบูชา = ประสูติ ตรัสรู้ ปรินิพพาน (ขึ้น 15 ค่ำ เดือน 6)', 'วิสาขะ = 3 เหตุการณ์อัศจรรย์วันเพ็ญเดือน 6', '["วันสำคัญทางพุทธศาสนา","Regular","L1"]');
