INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('ENG_001', 'english', 'ภาษาอังกฤษ', 'Gifted', 2, 'Subjunctive / Wish Clauses', 'I wish I ______ enough time to study for the Horwang entrance exam today.', '["had","have","will have","have had"]', 0, 'โครงสร้าง Wish ในปัจจุบันใช้ Past Simple (V.2) เพื่อแสดงความปรารถนาที่ตรงข้ามกับความเป็นจริง', 'Wish ในปัจจุบันต้องใช้กริยาช่อง 2 (had)', 'Wish + S + V.2', '["Subjunctive / Wish Clauses","Gifted","L2"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('ENG_002', 'english', 'ภาษาอังกฤษ', 'Regular', 2, 'Phrasal Verbs', 'Please ______ the air conditioner before leaving the classroom.', '["turn off","turn on","turn into","turn over"]', 0, 'turn off แปลว่า ปิด (เครื่องใช้ไฟฟ้า/ไฟ)', 'turn on = เปิด, turn off = ปิด', 'turn off = ปิดเครื่องใช้ไฟฟ้า', '["Phrasal Verbs","Regular","L2"]');
